211 :           AnonymousFunctionNamingPolicy.MAPPED) {
212 :         checks.add(nameMappedAnonymousFunctions);
213 :       } else if (options.anonymousFunctionNaming ==
214 :           AnonymousFunctionNamingPolicy.UNMAPPED) {
215 :         checks.add(nameUnmappedAnonymousFunctions);
216 :       }
