220 :     if (options.jqueryPass) {
221 :       checks.add(jqueryAliases);
222 :     }
223 : 
224 :     if (options.angularPass) {
225 :       checks.add(angularPass);
226 :     }
227 : 
228 :     checks.add(checkSideEffects);
229 : 
230 :     if (options.checkSuspiciousCode ||
231 :         options.enables(DiagnosticGroups.GLOBAL_THIS) ||
232 :         options.enables(DiagnosticGroups.DEBUGGER_STATEMENT_PRESENT)) {
233 :       checks.add(suspiciousCode);
234 :     }
235 : 
236 :     if (options.checkControlStructures
237 :         || options.enables(DiagnosticGroups.ES5_STRICT))  {
238 :       checks.add(checkControlStructures);
239 :     }
240 : 
241 :     if (options.checkRequires.isOn()) {
242 :       checks.add(checkRequires);
243 :     }
244 : 
245 :     if (options.checkProvides.isOn()) {
246 :       checks.add(checkProvides);
247 :     }
248 : 
249 :     // The following passes are more like "preprocessor" passes.
250 :     // It's important that they run before most checking passes.
251 :     // Perhaps this method should be renamed?
252 :     if (options.generateExports) {
253 :       checks.add(generateExports);
254 :     }
255 : 
256 :     if (options.exportTestFunctions) {
257 :       checks.add(exportTestFunctions);
258 :     }
259 : 
260 :     if (options.closurePass) {
261 :       checks.add(closurePrimitives);
262 :     }
263 : 
264 :     if (options.closurePass && options.checkMissingGetCssNameLevel.isOn()) {
265 :       checks.add(closureCheckGetCssName);
266 :     }
267 : 
268 :     if (options.syntheticBlockStartMarker != null) {
269 :       // This pass must run before the first fold constants pass.
270 :       checks.add(createSyntheticBlocks);
271 :     }
272 : 
273 :     checks.add(checkVars);
274 :     if (options.computeFunctionSideEffects) {
275 :       checks.add(checkRegExp);
276 :     }
277 : 
278 :     if (options.aggressiveVarCheck.isOn()) {
279 :       checks.add(checkVariableReferences);
280 :     }
281 : 
282 :     // This pass should run before types are assigned.
283 :     if (options.processObjectPropertyString) {
284 :       checks.add(objectPropertyStringPreprocess);
285 :     }
286 : 
287 :     checks.add(createEmptyPass("beforeTypeChecking"));
288 : 
289 :     if (options.checkTypes || options.inferTypes) {
290 :       checks.add(resolveTypes);
291 :       checks.add(inferTypes);
292 :       if (options.checkTypes) {
293 :         checks.add(checkTypes);
294 :       } else {
295 :         checks.add(inferJsDocInfo);
296 :       }
297 : 
298 :       // We assume that only IDE-mode clients will try to query the
299 :       // typed scope creator after the compile job.
300 :       if (!options.ideMode && !options.saveDataStructures) {
301 :         checks.add(clearTypedScopePass);
302 :       }
303 :     }
304 : 
305 :     if (options.checkUnreachableCode.isOn() ||
306 :         (options.checkTypes && options.checkMissingReturn.isOn())) {
307 :       checks.add(checkControlFlow);
308 :     }
309 : 
310 :     // CheckAccessControls only works if check types is on.
311 :     if (options.checkTypes &&
312 :         (options.enables(DiagnosticGroups.ACCESS_CONTROLS)
313 :          || options.enables(DiagnosticGroups.CONSTANT_PROPERTY))) {
314 :       checks.add(checkAccessControls);
315 :     }
316 : 
317 :     if (options.checkEventfulObjectDisposalPolicy !=
318 :         CheckEventfulObjectDisposal.DisposalCheckingPolicy.OFF) {
319 :       checks.add(checkEventfulObjectDisposal);
320 :     }
321 : 
322 :     if (options.checkGlobalNamesLevel.isOn()) {
323 :       checks.add(checkGlobalNames);
324 :     }
325 : 
326 :     if (options.enables(DiagnosticGroups.ES5_STRICT) || options.checkCaja) {
327 :       checks.add(checkStrictMode);
328 :     }
329 : 
330 :     // Replace 'goog.getCssName' before processing defines but after the
331 :     // other checks have been done.
332 :     if (options.closurePass) {
333 :       checks.add(closureReplaceGetCssName);
334 :     }
335 : 
336 :     // i18n
337 :     // If you want to customize the compiler to use a different i18n pass,
338 :     // you can create a PassConfig that calls replacePassFactory
339 :     // to replace this.
340 :     if (options.replaceMessagesWithChromeI18n) {
341 :       checks.add(replaceMessagesForChrome);
342 :     } else if (options.messageBundle != null) {
343 :       checks.add(replaceMessages);
344 :     }
345 : 
346 :     if (options.getTweakProcessing().isOn()) {
347 :       checks.add(processTweaks);
348 :     }
349 : 
350 :     // Defines in code always need to be processed.
351 :     checks.add(processDefines);
352 : 
353 :     if (options.instrumentationTemplate != null ||
354 :         options.recordFunctionInformation) {
355 :       checks.add(computeFunctionNames);
356 :     }
357 : 
358 :     if (options.nameReferenceGraphPath != null &&
359 :         !options.nameReferenceGraphPath.isEmpty()) {
360 :       checks.add(printNameReferenceGraph);
361 :     }
362 : 
363 :     if (options.nameReferenceReportPath != null &&
364 :         !options.nameReferenceReportPath.isEmpty()) {
365 :       checks.add(printNameReferenceReport);
366 :     }
367 : 
368 :     checks.add(createEmptyPass("afterStandardChecks"));
369 : 
370 :     assertAllOneTimePasses(checks);
371 :     return checks;
372 :   }"

