"125 :   private static void applyFullCompilationOptions(CompilerOptions options) {
126 :     // Do not call applySafeCompilationOptions(options) because the call can
127 :     // create possible conflicts between multiple diagnostic groups.
128 : 
129 :     // All the safe optimizations.
130 :     options.dependencyOptions.setDependencySorting(true);
131 :     options.closurePass = true;
132 :     options.foldConstants = true;
133 :     options.coalesceVariableNames = true;
134 :     options.deadAssignmentElimination = true;
135 :     options.extractPrototypeMemberDeclarations = true;
136 :     options.collapseVariableDeclarations = true;
137 :     options.convertToDottedProperties = true;
138 :     options.labelRenaming = true;
139 :     options.removeDeadCode = true;
140 :     options.optimizeArgumentsArray = true;
141 :     options.collapseObjectLiterals = true;
142 :     options.protectHiddenSideEffects = true;
143 : 
144 :     // All the advanced optimizations.
145 :     options.removeClosureAsserts = true;
146 :     options.reserveRawExports = true;
147 :     options.setRenamingPolicy(
148 :         VariableRenamingPolicy.ALL, PropertyRenamingPolicy.ALL_UNQUOTED);
149 :     options.shadowVariables = true;
150 :     options.removeUnusedPrototypeProperties = true;
151 :     options.removeUnusedPrototypePropertiesInExterns = true;
152 :     options.removeUnusedClassProperties = true;
153 :     options.collapseAnonymousFunctions = true;
154 :     options.collapseProperties = true;
155 :     options.checkGlobalThisLevel = CheckLevel.WARNING;
156 :     options.rewriteFunctionExpressions = false;
157 :     options.smartNameRemoval = true;
158 :     options.inlineConstantVars = true;
159 :     options.setInlineFunctions(Reach.ALL);
160 :     options.setAssumeClosuresOnlyCaptureReferences(false);
161 :     options.inlineGetters = true;
162 :     options.setInlineVariables(Reach.ALL);
163 :     options.flowSensitiveInlineVariables = true;
164 :     options.computeFunctionSideEffects = true;
165 : 
166 :     // Remove unused vars also removes unused functions.
167 :     options.setRemoveUnusedVariables(Reach.ALL);
168 : 
169 :     // Move code around based on the defined modules.
170 :     options.crossModuleCodeMotion = true;
171 :     options.crossModuleMethodMotion = true;
172 : 
173 :     // Call optimizations
174 :     options.devirtualizePrototypeMethods = true;
175 :     options.optimizeParameters = true;
176 :     options.optimizeReturns = true;
177 :     options.optimizeCalls = true;
178 :   }"

